<style>tr.rowhl td{background:#FEF08A!important;transition:background .6s}.qa-btn{width:30px;height:30px;padding:0;border:1px solid #E5E7EB;background:#fff;color:#0F172A;border-radius:6px;font-size:18px;line-height:1;cursor:pointer;vertical-align:middle}.qa-btn:hover{border-color:#FF5A00;background:#FFF7ED}
#qaPop{position:fixed;z-index:9999;display:none;width:152px;background:#fff;border:1px solid #E5E7EB;border-radius:6px;box-shadow:0 4px 14px rgba(15,23,42,.15);padding:4px}#qaPop button,#qaPop a{display:block;width:100%;height:28px;line-height:28px;margin:0 0 4px;padding:0 8px;border:0;border-radius:4px;font-size:12px;font-weight:600;text-align:left;color:#fff;cursor:pointer;text-decoration:none;box-sizing:border-box}#qaPop :last-child{margin-bottom:0}#qaPop .cur{opacity:.55;cursor:default}#qaPop .cur:after{content:" ✓"}</style>
<div id="qaPop"></div>
<script>(function(){var pop=document.getElementById('qaPop'),cur=null,tok=document.querySelector('meta[name=csrf-token]'),T=tok?tok.content:'';
var L=[['Approved','#16A34A'],['Scheduled','#0D9488'],['Pending','#EA580C'],['WFP','#7C3AE0'],['Packaging','#6D28D9'],['Shipment','#0891B2'],['Delivered','#15803D'],['Return Pending','#B45309'],['Returned','#92400E'],['Cancel','#DC2626']],CONF={'Cancel':1,'Returned':1,'Return Pending':1};
function close(){pop.style.display='none';cur=null}
function open(b){var id=b.dataset.id,st=b.dataset.st;cur=b;var h='';L.forEach(function(x){h+='<button type="button" data-s="'+x[0]+'" class="'+(x[0]===st?'cur':'')+'" style="background:'+x[1]+'">'+x[0]+'</button>'});h+='<a href="/admin/orders/'+id+'/edit" style="background:#06B6D4">Edit</a><a href="/admin/orders/'+id+'" style="background:#0F172A">View</a>';pop.innerHTML=h;pop.style.display='block';var r=b.getBoundingClientRect(),ph=pop.offsetHeight,top=r.bottom+4;if(top+ph>innerHeight-8)top=Math.max(8,r.top-ph-4);var left=Math.min(r.left,innerWidth-pop.offsetWidth-8);pop.style.top=top+'px';pop.style.left=Math.max(8,left)+'px'}
document.addEventListener('click',function(e){var b=e.target.closest('.qa-btn');if(b){e.preventDefault();var same=cur===b&&pop.style.display==='block';close();if(!same)open(b);return}var s=e.target.closest('#qaPop button[data-s]');if(s&&!s.classList.contains('cur')){var to=s.dataset.s,row=cur.closest('tr'),id=cur.dataset.id;if(CONF[to]&&!confirm('Change status to '+to+'?'))return;s.disabled=true;fetch('/admin/orders/'+id+'/quick-status',{method:'POST',headers:{'X-CSRF-TOKEN':T,'Accept':'application/json','Content-Type':'application/json','X-Requested-With':'XMLHttpRequest'},body:JSON.stringify({status:to})}).then(function(r){return r.json()}).then(function(j){if(!j.success)throw new Error('failed');close();if(window.ordGo)window.ordGo(j.status,[id]);else{var p=row.querySelector('.pill');if(p){p.className='pill '+j.cls;p.textContent=j.status}}}).catch(function(){s.disabled=false;alert('Status change failed')});return}if(!e.target.closest('#qaPop'))close()});
addEventListener('scroll',close,true);addEventListener('resize',close);document.addEventListener('keydown',function(e){if(e.key==='Escape')close()})})();</script>
